-- =====================================================================
-- SYNQRA Unit 11 CDU Balongan - Tambah Tabel Literatur & Kolom Referensi
-- Aman dijalankan berkali-kali (idempotent) tanpa menghapus data kasus.
-- =====================================================================

CREATE TABLE IF NOT EXISTS public.literature_references (
  code TEXT PRIMARY KEY,
  citation TEXT NOT NULL,
  year INTEGER NOT NULL,
  category TEXT NOT NULL,
  doi_or_url TEXT DEFAULT '',
  key_findings TEXT NOT NULL,
  is_balongan_specific BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE public.reports ADD COLUMN IF NOT EXISTS literature_refs TEXT[] DEFAULT '{}'::TEXT[];
ALTER TABLE public.reports ADD COLUMN IF NOT EXISTS journal_image_ids TEXT[] DEFAULT '{}'::TEXT[];

ALTER TABLE public.literature_references ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "synqra_literature_read" ON public.literature_references;
CREATE POLICY "synqra_literature_read" ON public.literature_references FOR SELECT TO anon, authenticated USING (true);
DROP POLICY IF EXISTS "synqra_literature_write" ON public.literature_references;
CREATE POLICY "synqra_literature_write" ON public.literature_references FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);

-- Upsert 32 paper & referensi ilmiah Unit 11 CDU Balongan:
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('PE25', 'Permana, M. S., Soeweify, M. P., Nugroho, B., Yusupandi, F., Devianto, H., & Prakoso, A. D. (2025). Innovation in Inspection Planning Using CAIS to Prevent Stationary Equipment Failure in CDU. Scientific Contributions Oil & Gas (LEMIGAS), 48(3), 203-214.', 2025, 'Jurnal LEMIGAS · CDU RU VI Balongan', 'https://doi.org/10.29017/scog.v48i3.1848', 'Memetakan 9 mekanisme korosi API 571/581 di CDU RU VI Balongan; TAN HGO 1,10-1,65 dan residu 1,00-1,24 mg KOH/g; ambang laju korosi CAIS Low < 0,05, Moderate 0,05-0,51, High 0,51-1,27, Severe > 1,27 mm/tahun; titik sampling kritis 11-FV-031, 11-V-102, 11-V-104, 11-E-128 A/B.', true) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('AL24', 'Alhanif, M., Frastia, W., Kamil, M. I., Kumoro, A. C., Yusupandi, F., dkk. (2024). Evaluasi Kinerja Alat Penukar Panas 11-E-107 pada Unit Distilasi Minyak Mentah (CDU). Distilat: Jurnal Teknologi Separasi, 10(2), 382-392.', 2024, 'Jurnal · Hot Preheater 11-E-107 CDU Balongan', 'https://doi.org/10.33795/distilat.v10i2.4713', 'Evaluasi aktual 11-E-107 Unit 11 CDU Balongan (Juni 2023): efisiensi desain 94,3% vs aktual 87,6-91,5%, dengan batas tindakan pembersihan (cleaning action limit) saat efisiensi turun < 80%.', true) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('PN25', 'Prasetya, E. A. (2025). Analisis Kebocoran dan Tahapan Penggantian Mechanical Seal pada Pompa di PT KPI RU VI Balongan. Politeknik Negeri Jakarta.', 2025, 'Studi Lapangan · Mechanical Seal RU VI Balongan', 'https://repository.pnj.ac.id/25731/', 'Standar verifikasi pasca-perbaikan mechanical seal pompa proses di RU VI Balongan mencakup laser alignment kopling, pengukuran vibrasi, dan uji observasi kebocoran 30-60 menit.', true) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('RDMP22', 'Kementerian ESDM & PT KPI RU VI Balongan (2022). Proyek Strategis Nasional RDMP RU VI Balongan Phase 1: Revamping Unit 11 CDU & Instalasi Pre-Flash Column 11-C-106.', 2022, 'Dokumentasi Rekayasa · RDMP Unit 11 Balongan', 'https://migas.esdm.go.id/', 'Peningkatan kapasitas Unit 11 CDU Balongan dari 125 MBSD ke 150 MBSD dan naphtha dari 5,29 ke 11,6 MBSD melalui penambahan Pre-Flash Column 11-C-106 (33,56 m x 5,14 m, 72 ton, fabrikasi PT BBI) dan Condenser Drum 11-V-116.', true) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('MB17', 'Musyarofah, S., Ibrahim, P. A., & Putra, A. B. (2017). Analisa Kinerja Desalter pada Crude Distillation Unit. Jurnal Migasian AKAMIGAS Balongan, 1(2).', 2017, 'Jurnal · Desalter Unit 11 CDU Balongan', 'https://jurnal.akamigasbalongan.ac.id/', 'Analisis efisiensi penghilangan garam dan sedimen pada Electrostatic Desalter 11-V-101 A/B CDU Balongan (~150 derajat C, 8 kg/cm2g) untuk mencegah korosi HCl di perpipaan overhead dan fouling preheater.', true) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('YP11', 'Perdana, Y. (2011). Studi Perancangan Kontrol Prediktif (MPC) pada Kolom Distilasi di Crude Distillation Unit PT Pertamina RU VI Balongan. Jurnal Otomasi Kontrol & Instrumentasi ITB, 2(2), 105.', 2011, 'Jurnal ITB · Kontrol Kolom 11-C-101 Balongan', 'https://journals.itb.ac.id/index.php/joki/', 'Pemodelan interaksi multi-variabel suhu top dan side-stream (kerosene, LGO, HGO) serta sirkuit pump-around (11-P-104/105/106) pada Main Fractionator 11-C-101 (34 tray, umpan tray 31).', true) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
