INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('CA22', 'Cao, Q., dkk. (2022). A Review of Corrosion Under Insulation (CUI) in the Oil and Gas Industry. Metals, 12(4), 561.', 2022, 'Jurnal CC BY 4.0 · Corrosion Under Insulation', 'https://doi.org/10.3390/met12040561', 'Zona paling rawan CUI baja karbon berada pada 50-175 derajat C (API RP 583); deteksi dini efektif menggunakan termografi IR siang/malam untuk memetakan insulasi basah.', false) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('AR23', 'Ardy, H., Albatros, T., & Sumboja, A. (2023). Failure Analysis of Heat Exchanger Tubes with Cooling Medium. Metals, 13(7), 1182.', 2023, 'Jurnal ITB CC BY 4.0 · Kegagalan Tube & MIC Exchanger', 'https://doi.org/10.3390/met13071182', 'Studi peneliti ITB atas kebocoran tube heat exchanger akibat skala CaCO3 (aragonit/dolomit) dan crevice corrosion yang diperparah bakteri MIC pada aliran lambat.', false) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('EL22', 'Elkatory, M. R., dkk. (2022). Mitigation of Waxy Crude Oils Deposition. Polymers, 14(16), 3231.', 2022, 'Jurnal CC BY 4.0 · Deposisi Wax Minyak Parafinik', 'https://doi.org/10.3390/polym14163231', 'Pendinginan di bawah Wax Appearance Temperature (WAT) pada minyak parafinik (seperti Minas/Duri) mengendapkan kristal parafin di dinding cooler dan menaikkan pressure drop.', false) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('YA25', 'Yang, Y., dkk. (2025). Performance Prediction of Fouled Spiral Fin-Tube Heat Exchanger. Modelling, 6(4), 138.', 2025, 'Jurnal CC BY · Fouling Debu Fin-Fan Air Cooler', 'https://doi.org/10.3390/modelling6040138', 'Akumulasi partikel debu paling tebal terjadi di sisi udara masuk baris tube terbawah fin-fan, menurunkan bilangan Nusselt dan kapasitas pendinginan siang hari.', false) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('HO22', 'Hou, X., dkk. (2022). Root Cause Failure Analysis of Deep-Groove Ball Bearing. Applied Sciences, 12(19), 9658.', 2022, 'Jurnal CC BY · Spalling & Misalignment Bearing', 'https://doi.org/10.3390/app12199658', 'Ketidaksejajaran dudukan memicu beban aksial asimetris yang mengawali fatigue spalling pada raceway bearing (terdeteksi lewat frekuensi BPFO/BPFI).', false) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('KH23', 'Khan, K. A., & Ahmed, I. (2023). Performance Analysis of Gasketed Bolted Flange Joints. JMES, 17(3), 9564-9575.', 2023, 'Jurnal OA · Relaksasi Baut & Gasket Spiral Wound', 'https://doi.org/10.15282/jmes.17.3.2023.3.0757', 'Tegangan duduk gasket spiral wound turun 20-30% pada pemanasan 200-300 derajat C; ketidakseragaman torsi baut memicu rembesan saat start-up.', false) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;
INSERT INTO public.literature_references (code, citation, year, category, doi_or_url, key_findings, is_balongan_specific) VALUES ('PL23', 'Platvoet, E. (2023). Fouling in Fired Heaters: Burner Fouling. Digital Refining.', 2023, 'Referensi Rekayasa · Burner Tip Fouling Furnace', 'https://www.digitalrefining.com/', 'Kondensat hidrokarbon berat di fuel gas menyumbat gas tip burner, memicu flame impingement dan hot spot lokal pada radiant coil.', false) ON CONFLICT (code) DO UPDATE SET citation = EXCLUDED.citation, year = EXCLUDED.year, category = EXCLUDED.category, doi_or_url = EXCLUDED.doi_or_url, key_findings = EXCLUDED.key_findings, is_balongan_specific = EXCLUDED.is_balongan_specific;

